largeSquare.setFill(GOLD, 0.22);

function triangleVertices(layout) {
  const b = L-a;
  if (layout === 0) return [
    [p(0,0),p(a,0),p(0,b)],
    [p(L,0),p(L,a),p(a,0)],
    [p(L,L),p(b,L),p(L,a)],
    [p(0,L),p(0,b),p(b,L)]
  ];
  return [
    [p(a,0),p(a,a),p(L,a)],
