await Promise.all([firstEquation.waitForRender(), secondEquation.waitForRender(), conclusion.waitForRender()]);
firstEquation.scale(0.62).moveTo([3.1, 1.15, 0]);
secondEquation.scale(0.57).moveTo([3.1, 0.15, 0]);
